// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Constants} from "../Constants.sol";

library LiquityMath {
 uint256 internal constant NICR_PRECISION = 1e20;

 function _min(uint256 a, uint256 b) internal pure returns (uint256) {
 return a < b ? a : b;
 }

 function _max(uint256 a, uint256 b) internal pure returns (uint256) {
 return a >= b ? a : b;
 }

 // Exponentiation by squaring on a 1e18 fixed-point base. Used for baseRate decay.
 function _decPow(uint256 base, uint256 exp) internal pure returns (uint256) {
 if (exp == 0) return Constants.DECIMAL_PRECISION;

 uint256 y = Constants.DECIMAL_PRECISION;
 uint256 x = base;
 uint256 n = exp;

 while (n > 1) {
 if (n % 2 == 0) {
 x = (x * x) / Constants.DECIMAL_PRECISION;
 n = n / 2;
 } else {
 y = (x * y) / Constants.DECIMAL_PRECISION;
 x = (x * x) / Constants.DECIMAL_PRECISION;
 n = (n - 1) / 2;
 }
 }
 return (x * y) / Constants.DECIMAL_PRECISION;
 }

 // ICR = coll * price / debt (all 1e18). Returns max uint if debt is zero.
 function _computeCR(uint256 coll, uint256 debt, uint256 price) internal pure returns (uint256) {
 if (debt == 0) return type(uint256).max;
 return (coll * price) / debt;
 }

 // NICR = coll * 1e20 / debt price-independent ranking for SortedTroves.
 function _computeNominalCR(uint256 coll, uint256 debt) internal pure returns (uint256) {
 if (debt == 0) return type(uint256).max;
 return (coll * NICR_PRECISION) / debt;
 }
}

src/PriceFeed.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IDIAOracle} from "./interfaces/IDIAOracle.sol";
import {IPriceFeed} from "./interfaces/IPriceFeed.sol";
import {Constants} from "./Constants.sol";

// PriceFeed — wraps the DIA oracle at 0x45dDa5d881BD2C917976CCfde74fFd6f6412da29
// on LitVM LiteForge (chainId 4441).
//
// DIA returns prices with 8 decimals. This contract scales to 18 decimals
// for internal protocol use.
//
// Security:
//   - Staleness check: rejects prices older than 1 hour
//   - Deviation check: rejects any single update that moves >20% from
//     lastGoodPrice — blocks flash-loan oracle manipulation
//   - Fallback: optional second DIA feed. If primary fails, tries fallback.
//   - Grace period: both feeds must be down for 1 hour before Shutdown
//   - No admin write path: nobody can manually set a price
//
// Pair key: "LTC/USD" — DIA's identifier for Litecoin/USD
contract PriceFeed is IPriceFeed {
    IDIAOracle public immutable primary;
    IDIAOracle public immutable fallbackOracle; // address(0) = no fallback

    // The DIA key for the asset pair
    string public constant PAIR_KEY = "LTC/USD";

    // DIA returns 8-decimal prices — scale to 18 for protocol math
    uint256 private constant DIA_DECIMALS    = 8;
    uint256 private constant SCALE_TO_18     = 10 ** (18 - DIA_DECIMALS); // 1e10

    // Max single-update price deviation: 20%
    uint256 private constant MAX_DEVIATION   = 20e16;

    uint256 public lastGoodPrice;
    uint256 public outageStart;
    Status  public status;

    event PriceUpdated(uint256 price18, address source);
    event OutageStarted(uint256 timestamp);
    event ShutdownEntered(uint256 timestamp);
    event PriceDeviationRejected(uint256 newPrice, uint256 lastGoodPrice, uint256 deviation);

    error InvalidOracle();
    error NoLastGoodPrice();

    constructor(address _primary, address _fallback) {
        if (_primary == address(0)) revert InvalidOracle();
        primary        = IDIAOracle(_primary);
        fallbackOracle = IDIAOracle(_fallback); // zero = no fallback
        status         = Status.Live;
    }

    function getLastGoodPrice() external view override returns (uint256) {
        return lastGoodPrice;
    }

    function fetchPrice() external override returns (uint256 price18, bool isLive) {
        if (status == Status.Shutdown) {
            if (lastGoodPrice == 0) revert NoLastGoodPrice();
            return (lastGoodPrice, false);
        }

        // Try primary DIA feed
        (uint256 p, bool ok) = _readDIA(primary);
        if (ok && _deviationOk(p)) {
            lastGoodPrice = p;
            outageStart   = 0;
            status        = Status.Live;
            emit PriceUpdated(p, address(primary));
            return (p, true);
        }

        // Try fallback DIA feed
        if (address(fallbackOracle) != address(0)) {
            (uint256 fp, bool fok) = _readDIA(fallbackOracle);
            if (fok && _deviationOk(fp)) {
                lastGoodPrice = fp;
                outageStart   = 0;
                status        = Status.Live;
                emit PriceUpdated(fp, address(fallbackOracle));
                return (fp, true);
            }
        }

        // Both feeds bad — track outage clock
        if (outageStart == 0) {
            outageStart = block.timestamp;
            status      = Status.ShutdownGrace;
            emit OutageStarted(block.timestamp);
        } else if (block.timestamp - outageStart >= Constants.SHUTDOWN_GRACE_PERIOD) {
            status = Status.Shutdown;
            emit ShutdownEntered(block.timestamp);
        }

        if (lastGoodPrice == 0) revert NoLastGoodPrice();
        return (lastGoodPrice, false);
    }

    // ─── Internal ─────────────────────────────────────────────────────────────

    function _readDIA(IDIAOracle oracle)
        internal
        view
        returns (uint256 price18, bool ok)
    {
        try oracle.getValue(PAIR_KEY) returns (uint128 price, uint128 timestamp) {
            if (price == 0)     return (0, false);
            if (timestamp == 0) return (0, false);
            // Staleness check
            if (block.timestamp - uint256(timestamp) > Constants.PRICE_STALENESS_THRESHOLD) {
                return (0, false);
            }
            // Scale 8-dec DIA price → 18-dec internal
            price18 = uint256(price) * SCALE_TO_18;
            ok      = price18 > 0;
        } catch {
            return (0, false);
        }
    }

    // Reject if new price moves >20% from last known good in one update
    function _deviationOk(uint256 newPrice) internal returns (bool) {
        if (lastGoodPrice == 0) return true; // first price — accept anything

        uint256 deviation;
        if (newPrice >= lastGoodPrice) {
            deviation = ((newPrice - lastGoodPrice) * Constants.DECIMAL_PRECISION) / lastGoodPrice;
        } else {
            deviation = ((lastGoodPrice - newPrice) * Constants.DECIMAL_PRECISION) / lastGoodPrice;
        }

        if (deviation > MAX_DEVIATION) {
            emit PriceDeviationRejected(newPrice, lastGoodPrice, deviation);
            return false;
        }
        return true;
    }
}

src/RedemptionHelper.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IAddressesRegistry} from "./interfaces/IAddressesRegistry.sol";
import {IActivePool} from "./interfaces/IPools.sol";
import {IFnUSD} from "./interfaces/IFnUSD.sol";
import {IPriceFeed} from "./interfaces/IPriceFeed.sol";
import {ISortedTroves} from "./interfaces/ISortedTroves.sol";
import {ITroveManager} from "./interfaces/ITroveManager.sol";
import {Constants} from "./Constants.sol";
import {LiquityMath} from "./libraries/LiquityMath.sol";
import {Decimals} from "./libraries/Decimals.sol";

// RedemptionHelper FnUSD → zkLTC one-way redemption.
//
// Security hardening:
// [1] ReentrancyGuard prevents re-entry via token callbacks
// [5] SortedTroves re-insertion handled by TroveManager.adjustTrove
// (TroveManager detects redemptionHelper caller and re-inserts)
// [6] Price manipulation protection redemptions blocked if oracle is not live.
// Additionally, redemptions only touch Troves from the riskiest end of the
// list, so a manipulated price cannot be used to drain a healthy Trove.
contract RedemptionHelper is ReentrancyGuard {
 using SafeERC20 for IERC20;

 IAddressesRegistry public immutable registry;

 uint256 public baseRate;
 uint256 public lastFeeOperationTime;

 // No minimum redemption — users can redeem any amount.

 event Redemption(
 address indexed redeemer,
 uint256 fnUSDAmount18,
 uint256 collateralSent,
 uint256 feePaid,
 uint256 newBaseRate
 );
 event BaseRateUpdated(uint256 newBaseRate);
 event LastFeeOpTimeUpdated(uint256 timestamp);

 error ZeroAmount();
 error InsufficientFnUSDBalance();
 error NoRedeemableTroves();
 error PriceFeedDown();

 constructor(IAddressesRegistry _registry) {
 registry = _registry;
 lastFeeOperationTime = block.timestamp;
 }

 // ─── redeem ───────────────────────────────────────────────────────────────

 function redeem(
 uint256 fnUSDAmount6,
 address firstHint,
 uint256 maxIterations
 ) external nonReentrant returns (uint256 collateralOut) {
 if (fnUSDAmount6 == 0) revert ZeroAmount();

 uint256 amount18 = Decimals.to18(fnUSDAmount6);

 IAddressesRegistry.Addresses memory a = registry.addresses();
 IFnUSD fnUSD = IFnUSD(a.fnUSD);
 ISortedTroves sortedTroves = ISortedTroves(a.sortedTroves);
 ITroveManager troveManager = ITroveManager(a.troveManager);
 IActivePool activePool = IActivePool(a.activePool);

 if (fnUSD.balanceOf(msg.sender) < fnUSDAmount6) revert InsufficientFnUSDBalance();

 // FIX [6]: block redemptions on stale/down oracle
 (uint256 price, bool isLive) = IPriceFeed(a.priceFeed).fetchPrice();
 if (!isLive) revert PriceFeedDown();

 _decayBaseRate();

 uint256 feeRate = _getRedemptionFeeRate();

 // Walk Troves from riskiest (tail) toward head
 address current = firstHint != address(0) ? firstHint : sortedTroves.getLast();
 if (current == address(0)) revert NoRedeemableTroves();

 uint256 remaining18 = amount18;
 uint256 iterations = 0;

 while (remaining18 > 0 && current != address(0)) {
 if (maxIterations != 0 && iterations >= maxIterations) break;

 // Read next before adjusting (adjustTrove re-inserts, changing list)
 address next = sortedTroves.getPrev(current);

 uint256 troveColl = troveManager.getTroveColl(current);
 uint256 troveDebt = troveManager.getTroveDebt(current);

 if (troveDebt == 0) { current = next; continue; }

 uint256 redeemDebt = LiquityMath._min(remaining18, troveDebt);
 uint256 redeemColl = (redeemDebt * Constants.DECIMAL_PRECISION) / price;

 if (redeemColl > troveColl) {
 redeemColl = troveColl;
 redeemDebt = (redeemColl * price) / Constants.DECIMAL_PRECISION;
 }

 // adjustTrove also re-inserts in SortedTroves (FIX [5])
 troveManager.adjustTrove(current, -int256(redeemColl), -int256(redeemDebt));

 if (troveDebt - redeemDebt == 0) {
 troveManager.closeTrove(current);
 }

 remaining18 -= redeemDebt;
 current = next;
 iterations++;
 }

 uint256 actualRedeemed18 = amount18 - remaining18;
 if (actualRedeemed18 == 0) revert NoRedeemableTroves();

 uint256 actualCollGross = (actualRedeemed18 * Constants.DECIMAL_PRECISION) / price;
 uint256 fee = (actualCollGross * feeRate) / Constants.DECIMAL_PRECISION;
 collateralOut = actualCollGross - fee;

 _updateBaseRateFromRedemption(actualRedeemed18, fnUSD.totalSupply());

 // Burn FnUSD state change before external calls (CEI)
 fnUSD.burn(msg.sender, actualRedeemed18);

 // Send fee to treasury, collateral to redeemer
 if (fee > 0) activePool.sendCollateral(a.treasury, fee);
 activePool.sendCollateral(msg.sender, collateralOut);

 emit Redemption(msg.sender, actualRedeemed18, collateralOut, fee, baseRate);
 }

 // ─── Fee views ────────────────────────────────────────────────────────────

 function getRedemptionFeeRate() external view returns (uint256) {
 return _getRedemptionFeeRate();
 }

 function getRedemptionRateWithDecay() external view returns (uint256) {
 return _calcDecayedBaseRate();
 }

 // ─── Internal ─────────────────────────────────────────────────────────────

 function _getRedemptionFeeRate() internal view returns (uint256) {
 return LiquityMath._max(Constants.REDEMPTION_FEE_FLOOR, baseRate);
 }

 function _decayBaseRate() internal {
 uint256 decayed = _calcDecayedBaseRate();
 baseRate = decayed;
 lastFeeOperationTime = block.timestamp;
 emit BaseRateUpdated(decayed);
 emit LastFeeOpTimeUpdated(block.timestamp);
 }

 function _calcDecayedBaseRate() internal view returns (uint256) {
 uint256 minutesPassed = (block.timestamp - lastFeeOperationTime) / 60;
 uint256 decayFactor = LiquityMath._decPow(Constants.MINUTE_DECAY_FACTOR, minutesPassed);
 return (baseRate * decayFactor) / Constants.DECIMAL_PRECISION;
 }

 function _updateBaseRateFromRedemption(
 uint256 redeemedFnUSD18,
 uint256 totalFnUSDSupply6
 ) internal {
 uint256 totalSupply18 = Decimals.to18(totalFnUSDSupply6);
 if (totalSupply18 == 0) return;

 uint256 redeemedFraction = (redeemedFnUSD18 * Constants.DECIMAL_PRECISION) / totalSupply18;
 uint256 newBaseRate = baseRate + (redeemedFraction / Constants.BETA);
 if (newBaseRate > Constants.ONE_HUNDRED_PCT) newBaseRate = Constants.ONE_HUNDRED_PCT;

 baseRate = newBaseRate;
 emit BaseRateUpdated(newBaseRate);
 }
}

src/SortedTroves.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ISortedTroves} from "./interfaces/ISortedTroves.sol";
import {ITroveManager} from "./interfaces/ITroveManager.sol";
import {IAddressesRegistry} from "./interfaces/IAddressesRegistry.sol";

// SortedTroves doubly-linked list of Trove owners ordered by NICR descending
// (head = highest NICR / safest, tail = lowest NICR / riskiest). NICR is
// price-independent so the list does not require resorting on price changes.
contract SortedTroves is ISortedTroves {
 IAddressesRegistry public immutable registry;

 struct Node {
 bool exists;
 address next; // toward tail (lower NICR)
 address prev; // toward head (higher NICR)
 }

 address public head;
 address public tail;
 uint256 public size;
 mapping(address => Node) public nodes;

 error NotAuthorized();
 error AlreadyExists();
 error NotFound();
 error ZeroNICR();

 constructor(IAddressesRegistry _registry) {
 registry = _registry;
 }

 modifier onlyTMorBO() {
 IAddressesRegistry.Addresses memory a = registry.addresses();
 if (msg.sender != a.troveManager && msg.sender != a.borrowerOperations) revert NotAuthorized();
 _;
 }

 function contains(address owner) external view returns (bool) { return nodes[owner].exists; }
 function isEmpty() external view returns (bool) { return size == 0; }
 function getSize() external view returns (uint256) { return size; }
 function getFirst() external view returns (address) { return head; }
 function getLast() external view returns (address) { return tail; }
 function getNext(address owner) external view returns (address) { return nodes[owner].next; }
 function getPrev(address owner) external view returns (address) { return nodes[owner].prev; }

 function insert(address owner, uint256 nicr, address prevHint, address nextHint) external onlyTMorBO {
 _insert(owner, nicr, prevHint, nextHint);
 }

 function remove(address owner) external onlyTMorBO {
 _remove(owner);
 }

 function reInsert(address owner, uint256 newNICR, address prevHint, address nextHint) external onlyTMorBO {
 _remove(owner);
 _insert(owner, newNICR, prevHint, nextHint);
 }

 function findInsertPosition(uint256 nicr, address prevHint, address nextHint)
 external view returns (address, address)
 {
 return _findInsertPosition(nicr, prevHint, nextHint);
 }

 function _insert(address owner, uint256 nicr, address prevHint, address nextHint) internal {
 if (nodes[owner].exists) revert AlreadyExists();
 if (nicr == 0) revert ZeroNICR();

 (address prev, address next) = _findInsertPosition(nicr, prevHint, nextHint);
 nodes[owner] = Node({exists: true, prev: prev, next: next});

 if (prev == address(0)) head = owner;
 else nodes[prev].next = owner;

 if (next == address(0)) tail = owner;
 else nodes[next].prev = owner;

 size++;
 }

 function _remove(address owner) internal {
 Node memory n = nodes[owner];
 if (!n.exists) revert NotFound();

 if (n.prev != address(0)) nodes[n.prev].next = n.next;
 else head = n.next;

 if (n.next != address(0)) nodes[n.next].prev = n.prev;
 else tail = n.prev;

 delete nodes[owner];
 size--;
 }

 // Returns the (prev, next) pair around the slot where `nicr` should sit.
 // Invariant: NICR(prev) >= nicr >= NICR(next).
 function _findInsertPosition(uint256 nicr, address prevHint, address nextHint)
 internal view returns (address prev, address next)
 {
 if (size == 0) return (address(0), address(0));

 ITroveManager tm = ITroveManager(registry.addresses().troveManager);

 // Validate hints; drop them if they no longer hold the invariant.
 if (prevHint != address(0) && (!nodes[prevHint].exists || tm.getNominalICR(prevHint) < nicr)) {
 prevHint = address(0);
 }
 if (nextHint != address(0) && (!nodes[nextHint].exists || tm.getNominalICR(nextHint) > nicr)) {
 nextHint = address(0);
 }

 if (prevHint == address(0) && nextHint == address(0)) {
 return _walkFromHead(nicr, tm);
 } else if (prevHint != address(0)) {
 return _walkFromPrev(nicr, prevHint, tm);
 } else {
 return _walkFromNext(nicr, nextHint, tm);
 }
 }

 function _walkFromHead(uint256 nicr, ITroveManager tm) internal view returns (address, address) {
 address cur = head;
 while (cur != address(0) && tm.getNominalICR(cur) > nicr) {
 cur = nodes[cur].next;
 }
 // cur is the first node with NICR <= nicr (or 0). prev is its predecessor.
 return (cur == address(0) ? tail : nodes[cur].prev, cur);
 }

 function _walkFromPrev(uint256 nicr, address start, ITroveManager tm)
 internal view returns (address prev, address next)
 {
 prev = start;
 // Walk forward (toward tail) while next still has higher NICR than nicr.
 next = nodes[prev].next;
 while (next != address(0) && tm.getNominalICR(next) > nicr) {
 prev = next;
 next = nodes[next].next;
 }
 }

 function _walkFromNext(uint256 nicr, address start, ITroveManager tm)
 internal view returns (address prev, address next)
 {
 next = start;
 // Walk backward while prev has lower NICR than nicr.
 prev = nodes[next].prev;
 while (prev != address(0) && tm.getNominalICR(prev) < nicr) {
 next = prev;
 prev = nodes[prev].prev;
 }
 }
}

src/TroveManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ITroveManager} from "./interfaces/ITroveManager.sol";
import {IAddressesRegistry} from "./interfaces/IAddressesRegistry.sol";
import {IActivePool, IDefaultPool, ICollSurplusPool} from "./interfaces/IPools.sol";
import {IFnUSD} from "./interfaces/IFnUSD.sol";
import {IPriceFeed} from "./interfaces/IPriceFeed.sol";
import {ISortedTroves} from "./interfaces/ISortedTroves.sol";
import {Constants} from "./Constants.sol";
import {LiquityMath} from "./libraries/LiquityMath.sol";
import {Decimals} from "./libraries/Decimals.sol";

// TroveManager — core accounting engine for all Troves.
contract TroveManager is ITroveManager, ReentrancyGuard {
    IAddressesRegistry public immutable registry;

    struct TroveData {
        uint256 debt;
        uint256 coll;
        uint256 stake;
        uint256 annualInterestRate;
        uint256 lastInterestTime;
        uint256 rewardSnapColl;
        uint256 rewardSnapDebt;
        Status  status;
    }

    mapping(address => TroveData) public troves;
    address[] public troveOwners;
    mapping(address => uint256) private _troveIndex;

    uint256 public L_coll;
    uint256 public L_debt;
    uint256 public totalStakes;

    uint256 private constant MAX_INTEREST_PERIOD = 10 * 365 days;

    event TroveOpened(address indexed owner, uint256 debt, uint256 coll, uint256 annualRate);
    event TroveUpdated(address indexed owner, uint256 debt, uint256 coll, uint256 stake, uint8 operation);
    event TroveLiquidated(address indexed owner, uint256 debt, uint256 coll, uint8 liquidationMode);
    event TroveClosed(address indexed owner, Status status);
    event Liquidation(uint256 liquidatedDebt, uint256 liquidatedColl, uint256 surplusColl);
    event InterestAccrued(address indexed owner, uint256 interest);

    error NotAuthorized();
    error TroveNotActive();
    error TroveAlreadyExists();
    error NothingToLiquidate();

    constructor(IAddressesRegistry _registry) {
        registry = _registry;
    }

    modifier onlyBO() {
        if (msg.sender != registry.addresses().borrowerOperations) revert NotAuthorized();
        _;
    }

    modifier onlyBOorRH() {
        IAddressesRegistry.Addresses memory a = registry.addresses();
        if (msg.sender != a.borrowerOperations && msg.sender != a.redemptionHelper) {
            revert NotAuthorized();
        }
        _;
    }

    modifier onlyRedemptionHelper() {
        if (msg.sender != registry.addresses().redemptionHelper) revert NotAuthorized();
        _;
    }

    // ─── View ─────────────────────────────────────────────────────────────────

    function getTroveOwnersCount() external view override returns (uint256) { return troveOwners.length; }
    function getTroveStatus(address owner) external view override returns (Status) { return troves[owner].status; }
    function getTroveColl(address owner) external view override returns (uint256) { return troves[owner].coll; }
    function getTroveDebt(address owner) external view override returns (uint256) { return troves[owner].debt; }
    function getTroveAnnualInterestRate(address owner) external view override returns (uint256) { return troves[owner].annualInterestRate; }

    function getCurrentICR(address owner, uint256 price) external view override returns (uint256) {
        (uint256 debt, uint256 coll,) = _getEntireDebtAndColl(owner);
        return LiquityMath._computeCR(coll, debt, price);
    }

    function getNominalICR(address owner) external view override returns (uint256) {
        (uint256 debt, uint256 coll,) = _getEntireDebtAndColl(owner);
        return LiquityMath._computeNominalCR(coll, debt);
    }

    function getEntireDebtAndColl(address owner)
        external view override
        returns (uint256 debt, uint256 coll, uint256 pendingInterest)
    {
        return _getEntireDebtAndColl(owner);
    }

    // ─── BorrowerOperations callbacks ─────────────────────────────────────────

    function openTrove(address owner, uint256 coll, uint256 debt) external override onlyBO nonReentrant {
        if (troves[owner].status == Status.Active) revert TroveAlreadyExists();

        TroveData storage t = troves[owner];
        t.debt               = debt;
        t.coll               = coll;
        t.annualInterestRate = Constants.ANNUAL_INTEREST_RATE;
        t.lastInterestTime   = block.timestamp;
        t.status             = Status.Active;
        t.rewardSnapColl     = L_coll;
        t.rewardSnapDebt     = L_debt;

        uint256 stake = _computeStake(coll);
        t.stake      = stake;
        totalStakes  += stake;

        _troveIndex[owner] = troveOwners.length;
        troveOwners.push(owner);

        emit TroveOpened(owner, debt, coll, Constants.ANNUAL_INTEREST_RATE);
        emit TroveUpdated(owner, debt, coll, stake, 0);
    }

    function adjustTrove(address owner, int256 collDelta, int256 debtDelta)
        external override onlyBOorRH nonReentrant
    {
        IAddressesRegistry.Addresses memory a = registry.addresses();
        TroveData storage t = troves[owner];
        if (t.status != Status.Active) revert TroveNotActive();

        _accrueInterest(owner, a);
        _applyPendingRewards(owner);

        if (collDelta > 0) t.coll += uint256(collDelta);
        else if (collDelta < 0) t.coll -= uint256(-collDelta);

        if (debtDelta > 0) t.debt += uint256(debtDelta);
        else if (debtDelta < 0) t.debt -= uint256(-debtDelta);

        totalStakes -= t.stake;
        t.stake      = _computeStake(t.coll);
        totalStakes += t.stake;

        t.rewardSnapColl = L_coll;
        t.rewardSnapDebt = L_debt;

        if (msg.sender == a.redemptionHelper) {
            uint256 newNICR = LiquityMath._computeNominalCR(t.coll, t.debt);
            ISortedTroves(a.sortedTroves).reInsert(owner, newNICR, address(0), address(0));
        }

        emit TroveUpdated(owner, t.debt, t.coll, t.stake, 1);
    }

    function closeTrove(address owner) external override onlyBOorRH nonReentrant {
        IAddressesRegistry.Addresses memory a = registry.addresses();
        TroveData storage t = troves[owner];
        if (t.status != Status.Active) revert TroveNotActive();

        _accrueInterest(owner, a);

        totalStakes -= t.stake;
        t.stake      = 0;
        t.status     = (msg.sender == a.redemptionHelper)
            ? Status.ClosedByRedemption
            : Status.ClosedByOwner;

        _removeTroveOwner(owner);

        emit TroveClosed(owner, t.status);
        emit TroveUpdated(owner, 0, 0, 0, 2);
    }

    // ─── Liquidation ──────────────────────────────────────────────────────────

    function liquidate(address owner) external override nonReentrant {
        address[] memory batch = new address[](1);
        batch[0] = owner;
        _batchLiquidate(batch);
    }

    function batchLiquidate(address[] calldata owners) external override nonReentrant {
        _batchLiquidate(owners);
    }

    function _batchLiquidate(address[] memory owners) internal {
        IAddressesRegistry.Addresses memory a = registry.addresses();
        (uint256 price,) = IPriceFeed(a.priceFeed).fetchPrice();

        uint256 totalLiquidatedDebt;
        uint256 totalLiquidatedColl;
        uint256 totalSurplus;
        bool    liquidatedAny;

        for (uint256 i = 0; i < owners.length; i++) {
            address owner = owners[i];
            TroveData storage t = troves[owner];
            if (t.status != Status.Active) continue;

            _accrueInterest(owner, a);
            _applyPendingRewards(owner);

            uint256 icr = LiquityMath._computeCR(t.coll, t.debt, price);
            if (icr >= Constants.MCR) continue;

            uint256 debt = t.debt;
            uint256 coll = t.coll;

            uint256 debtValueInColl = (debt * Constants.DECIMAL_PRECISION) / price;

            uint256 surplusColl;
            uint256 collForLP;
            uint256 collForTreasury;
            uint256 collForHolders;

            if (debtValueInColl <= coll) {
                surplusColl     = coll - debtValueInColl;
                collForLP       = debtValueInColl;
                collForTreasury = (surplusColl * Constants.LIQUIDATION_TREASURY_SHARE)
                                  / Constants.DECIMAL_PRECISION;
                collForHolders  = surplusColl - collForTreasury;
            } else {
                collForLP       = coll;
                collForTreasury = 0;
                collForHolders  = 0;
                surplusColl     = 0;
            }

            // Remove Trove O(1)
            totalStakes -= t.stake;
            t.stake      = 0;
            t.status     = Status.ClosedByLiquidation;
            _removeTroveOwner(owner);

            // Redistribute 20% holder share via DefaultPool
            if (collForHolders > 0 && totalStakes > 0) {
                uint256 debtForHolders = (debt * collForHolders) / coll;

                IActivePool(a.activePool).sendCollateral(a.defaultPool, collForHolders);
                IDefaultPool(a.defaultPool).creditCollateral(collForHolders);
                IDefaultPool(a.defaultPool).increaseDebt(debtForHolders);

                L_coll += (collForHolders * Constants.DECIMAL_PRECISION) / totalStakes;
                L_debt += (debtForHolders * Constants.DECIMAL_PRECISION) / totalStakes;
            }

            // LP portion + 80% treasury surplus → treasury (routes to Addax)
            uint256 toTreasury = collForLP + collForTreasury;
            if (toTreasury > 0) {
                IActivePool(a.activePool).sendCollateral(a.treasury, toTreasury);
            }

            // No burn — FnUSD debt absorbed by LP supply sent to Addax
            // No bot payment — protocol keeps everything

            totalLiquidatedDebt += debt;
            totalLiquidatedColl += coll;
            totalSurplus        += surplusColl;
            liquidatedAny        = true;

            emit TroveLiquidated(owner, debt, coll, 0);
            emit TroveUpdated(owner, 0, 0, 0, 4);
        }

        if (!liquidatedAny) revert NothingToLiquidate();
        emit Liquidation(totalLiquidatedDebt, totalLiquidatedColl, totalSurplus);
    }

    // ─── Redemption stub ──────────────────────────────────────────────────────

    function redeem(uint256, address, uint256) external override onlyRedemptionHelper returns (uint256) {
        revert NotAuthorized();
    }

    // ─── Fee views ────────────────────────────────────────────────────────────

    function baseRate() external pure override returns (uint256) { return 0; }
    function getRedemptionFeeRate() external pure override returns (uint256) { return Constants.REDEMPTION_FEE_FLOOR; }
    function getRedemptionRateWithDecay() external pure override returns (uint256) { return Constants.REDEMPTION_FEE_FLOOR; }

    // ─── Interest accrual ─────────────────────────────────────────────────────

    function _accrueInterest(address owner, IAddressesRegistry.Addresses memory a) internal {
        TroveData storage t = troves[owner];
        if (t.status != Status.Active) return;

        uint256 elapsed = block.timestamp - t.lastInterestTime;
        if (elapsed == 0) return;
        if (elapsed > MAX_INTEREST_PERIOD) elapsed = MAX_INTEREST_PERIOD;

        uint256 interest = (t.debt * t.annualInterestRate * elapsed)
            / (Constants.DECIMAL_PRECISION * Constants.SECONDS_PER_YEAR);

        if (interest == 0) return;

        t.debt            += interest;
        t.lastInterestTime = block.timestamp;

        IFnUSD(a.fnUSD).mint(a.treasury, interest);
        emit InterestAccrued(owner, interest);
    }

    // ─── Redistribution ───────────────────────────────────────────────────────

    function _applyPendingRewards(address owner) internal {
        TroveData storage t = troves[owner];
        if (t.status != Status.Active) return;

        uint256 pendingColl = (t.stake * (L_coll - t.rewardSnapColl)) / Constants.DECIMAL_PRECISION;
        uint256 pendingDebt = (t.stake * (L_debt - t.rewardSnapDebt)) / Constants.DECIMAL_PRECISION;

        if (pendingColl == 0 && pendingDebt == 0) return;

        t.coll += pendingColl;
        t.debt += pendingDebt;
        t.rewardSnapColl = L_coll;
        t.rewardSnapDebt = L_debt;

        IAddressesRegistry.Addresses memory a = registry.addresses();
        if (pendingColl > 0) {
            IDefaultPool(a.defaultPool).sendCollateralToActivePool(pendingColl);
            IDefaultPool(a.defaultPool).decreaseDebt(pendingDebt);
        }
    }

    function _computeStake(uint256 coll) internal pure returns (uint256) { return coll; }

    // O(1) swap-and-pop removal
    function _removeTroveOwner(address owner) internal {
        uint256 idx       = _troveIndex[owner];
        uint256 lastIdx   = troveOwners.length - 1;
        address lastOwner = troveOwners[lastIdx];

        troveOwners[idx]       = lastOwner;
        _troveIndex[lastOwner] = idx;

        troveOwners.pop();
        delete _troveIndex[owner];
    }

    function _getEntireDebtAndColl(address owner)
        internal view
        returns (uint256 debt, uint256 coll, uint256 pendingInterest)
    {
        TroveData storage t = troves[owner];

        uint256 pendingColl = (t.stake * (L_coll - t.rewardSnapColl)) / Constants.DECIMAL_PRECISION;
        uint256 pendingDebt = (t.stake * (L_debt - t.rewardSnapDebt)) / Constants.DECIMAL_PRECISION;

        uint256 elapsed = block.timestamp - t.lastInterestTime;
        if (elapsed > MAX_INTEREST_PERIOD) elapsed = MAX_INTEREST_PERIOD;

        pendingInterest = (t.debt * t.annualInterestRate * elapsed)
            / (Constants.DECIMAL_PRECISION * Constants.SECONDS_PER_YEAR);

        debt = t.debt + pendingDebt + pendingInterest;
        coll = t.coll + pendingColl;
    }
}

